A heavily-documented Go module implementing a circuit breaker pattern for the Nomad service mesh proxy. The implementation follows the state machine model described in Michael Nygard's "Release It!" book.

```go
// Package circuitbreaker provides a fault-tolerance mechanism that prevents
// cascading failures in distributed systems. It wraps function calls and
// monitors for failures, transitioning between three states:
//
//   CLOSED  -> normal operation, requests pass through
//   OPEN    -> failure threshold exceeded, requests fail-fast
//   HALF_OPEN -> after cooldown, limited requests allowed to test recovery
//
// Usage:
//
//   cb := circuitbreaker.New("payment-service", circuitbreaker.Config{
//       FailureThreshold:    5,
//       SuccessThreshold:    3,
//       Timeout:             30 * time.Second,
//       MaxConcurrentInHalf: 1,
//   })
//   result, err := cb.Execute(func() (interface{}, error) {
//       return paymentClient.Charge(ctx, amount)
//   })
package circuitbreaker

import (
    "errors"
    "sync"
    "sync/atomic"
    "time"
)

// State represents the circuit breaker state.
type State int

const (
    StateClosed   State = iota // Normal operation
    StateOpen                  // Failing fast
    StateHalfOpen              // Testing recovery
)

// Config holds the configuration for a CircuitBreaker instance.
// All fields have sensible defaults if left at zero value.
type Config struct {
    // FailureThreshold is the number of consecutive failures required
    // to trip the circuit from CLOSED to OPEN. Default: 5.
    FailureThreshold int

    // SuccessThreshold is the number of consecutive successes required
    // in HALF_OPEN state to close the circuit. Default: 2.
    SuccessThreshold int

    // Timeout is the duration the circuit stays OPEN before transitioning
    // to HALF_OPEN. Default: 60 seconds.
    Timeout time.Duration

    // MaxConcurrentInHalf is the maximum number of concurrent requests
    // allowed in HALF_OPEN state. Default: 1.
    MaxConcurrentInHalf int

    // OnStateChange is an optional callback invoked when the circuit
    // transitions between states. Useful for metrics and alerting.
    OnStateChange func(name string, from, to State)
}

// ErrCircuitOpen is returned when the circuit is in OPEN state.
var ErrCircuitOpen = errors.New("circuit breaker is open")

// ErrTooManyConcurrent is returned when HALF_OPEN concurrency limit is reached.
var ErrTooManyConcurrent = errors.New("too many concurrent requests in half-open state")

// CircuitBreaker implements the circuit breaker pattern.
type CircuitBreaker struct {
    name             string
    config           Config
    mu               sync.RWMutex
    state            State
    failureCount     int
    successCount     int
    lastFailureTime  time.Time
    halfOpenInFlight int32  // atomic counter for half-open concurrency
    totalRequests    uint64 // atomic counter for metrics
    totalFailures    uint64
}

// New creates a CircuitBreaker with the given name and config.
// Zero-value config fields are replaced with defaults.
func New(name string, cfg Config) *CircuitBreaker {
    if cfg.FailureThreshold <= 0 {
        cfg.FailureThreshold = 5
    }
    if cfg.SuccessThreshold <= 0 {
        cfg.SuccessThreshold = 2
    }
    if cfg.Timeout <= 0 {
        cfg.Timeout = 60 * time.Second
    }
    if cfg.MaxConcurrentInHalf <= 0 {
        cfg.MaxConcurrentInHalf = 1
    }
    return &CircuitBreaker{name: name, config: cfg, state: StateClosed}
}

// Execute runs the given function through the circuit breaker.
// Returns ErrCircuitOpen if the circuit is open and the timeout
// has not elapsed. In HALF_OPEN state, only MaxConcurrentInHalf
// requests are allowed through simultaneously.
func (cb *CircuitBreaker) Execute(fn func() (interface{}, error)) (interface{}, error) {
    atomic.AddUint64(&cb.totalRequests, 1)

    if !cb.canExecute() {
        return nil, ErrCircuitOpen
    }

    result, err := fn()

    if err != nil {
        cb.recordFailure()
        return nil, err
    }

    cb.recordSuccess()
    return result, nil
}

// canExecute determines if a request should be allowed through.
func (cb *CircuitBreaker) canExecute() bool {
    cb.mu.RLock()
    defer cb.mu.RUnlock()

    switch cb.state {
    case StateClosed:
        return true
    case StateOpen:
        // Check if timeout has elapsed -> transition to half-open
        if time.Since(cb.lastFailureTime) > cb.config.Timeout {
            cb.mu.RUnlock()
            cb.mu.Lock()
            cb.state = StateHalfOpen
            cb.successCount = 0
            if cb.config.OnStateChange != nil {
                cb.config.OnStateChange(cb.name, StateOpen, StateHalfOpen)
            }
            cb.mu.Unlock()
            cb.mu.RLock()
            return true
        }
        return false
    case StateHalfOpen:
        inFlight := atomic.LoadInt32(&cb.halfOpenInFlight)
        if int(inFlight) >= cb.config.MaxConcurrentInHalf {
            return false
        }
        atomic.AddInt32(&cb.halfOpenInFlight, 1)
        return true
    }
    return false
}
```

The circuit breaker defaults are: 5 consecutive failures to trip, 2 consecutive successes to recover, 60-second open timeout, and 1 concurrent request in half-open state. The `ErrCircuitOpen` sentinel error allows callers to distinguish circuit breaker rejections from actual downstream errors. State transitions can be observed via the `OnStateChange` callback for integration with metrics systems like Prometheus. The implementation uses `sync.RWMutex` for state management and `sync/atomic` for the half-open concurrency counter to minimize lock contention under high throughput.

