    line_id BIGSERIAL PRIMARY KEY,
    entry_id BIGINT NOT NULL REFERENCES journal_entries(entry_id),
    account_id BIGINT NOT NULL REFERENCES accounts(account_id),
    debit NUMERIC(15, 4) NOT NULL DEFAULT 0 CHECK (debit >= 0),
    credit NUMERIC(15, 4) NOT NULL DEFAULT 0 CHECK (credit >= 0),
    memo VARCHAR(500),
    CHECK (debit > 0 OR credit > 0),
    CHECK (NOT (debit > 0 AND credit > 0))
);

CREATE INDEX idx_journal_lines_account ON journal_lines (account_id, entry_id);
CREATE INDEX idx_journal_entries_date ON journal_entries (effective_date, status);
CREATE INDEX idx_journal_entries_ref ON journal_entries (reference_id);

-- Trigger: ensure balanced entries
CREATE OR REPLACE FUNCTION check_balanced_entry()
RETURNS TRIGGER AS $$
DECLARE
    total_debit NUMERIC;
    total_credit NUMERIC;
BEGIN
    SELECT COALESCE(SUM(debit), 0), COALESCE(SUM(credit), 0)
    INTO total_debit, total_credit
    FROM journal_lines WHERE entry_id = NEW.entry_id;

    IF total_debit <> total_credit THEN
        RAISE EXCEPTION 'Journal entry % is not balanced: debit=% credit=%',
            NEW.entry_id, total_debit, total_credit;
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

COMMIT;

